package com.ecole.gestion_scolaire.parentportal.service;
import com.ecole.gestion_scolaire.parentportal.dto.ParentPortalDtos.*; import com.ecole.gestion_scolaire.security.service.SecurityUser; import jakarta.persistence.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.sql.*; import java.time.*; import java.util.*;
@Service @Transactional(readOnly=true) public class ParentPortalService { @PersistenceContext private EntityManager em;
 private SecurityUser current(){Object p=SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(!(p instanceof SecurityUser s))throw new IllegalStateException("Utilisateur non authentifié.");return s;}
 private Long guardianId(){Long pid=current().getUserAccount().getPerson().getId();List<?> x=em.createNativeQuery("select id from guardian where person_id=:p and status <> 'ARCHIVED' order by id desc limit 1").setParameter("p",pid).getResultList();if(x.isEmpty())throw new IllegalStateException("Aucun profil parent n'est rattaché à ce compte.");return ((Number)x.get(0)).longValue();}
 public Me me(){var s=current();Long personId=s.getUserAccount().getPerson().getId();Object[] p=(Object[])em.createNativeQuery("select first_name,last_name,email from person where id=:personId").setParameter("personId",personId).getSingleResult();return new Me(guardianId(),s.getUsername(),str(p[0]),str(p[1]),str(p[2]));}
 public List<Child> children(){Long g=guardianId();List<Object[]> rows=em.createNativeQuery("select s.id,s.student_number,p.first_name,p.last_name,e.id,e.current_class_group_id,cg.name,sg.financial_responsible from student_guardian sg join student s on s.id=sg.student_id join person p on p.id=s.person_id left join lateral (select se.* from student_enrollment se where se.student_id=s.id and se.status='ACTIVE' order by se.enrollment_date desc,se.id desc limit 1) e on true left join class_group cg on cg.id=e.current_class_group_id where sg.guardian_id=:g and sg.active=true order by p.last_name,p.first_name").setParameter("g",g).getResultList();List<Child> out=new ArrayList<>();for(Object[] r:rows)out.add(new Child(l(r[0]),str(r[1]),str(r[2]),str(r[3]),l(r[4]),l(r[5]),str(r[6]),Boolean.TRUE.equals(r[7])));return out;}
 private Child owned(Long studentId){return children().stream().filter(c->Objects.equals(c.studentId(),studentId)).findFirst().orElseThrow(()->new SecurityException("Cet élève n'est pas rattaché au parent connecté."));}
 public Dashboard dashboard(){var cs=children();BigDecimal due=BigDecimal.ZERO,paid=BigDecimal.ZERO;long overdue=0;for(var c:cs){var f=finance(c.studentId());due=due.add(f.totalDue());paid=paid.add(f.totalPaid());overdue+=f.overdueCharges();}return new Dashboard(cs.size(),due,paid,due.subtract(paid).max(BigDecimal.ZERO),overdue);}
 public FinanceSummary finance(Long sid){Child c=owned(sid);if(c.enrollmentId()==null)return new FinanceSummary(sid,BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,0);Object[] r=(Object[])em.createNativeQuery("select coalesce(sum(sc.final_amount),0),coalesce(sum((select coalesce(sum(pa.amount),0) from payment_allocation pa join payment p on p.id=pa.payment_id where pa.student_charge_id=sc.id and p.status not in ('CANCELLED','ANNULE'))),0),count(*) filter(where sc.due_date<current_date and sc.status not in ('PAID','CANCELLED','ANNULE')) from student_charge sc where sc.student_enrollment_id=:e and sc.status not in ('CANCELLED','ANNULE')").setParameter("e",c.enrollmentId()).getSingleResult();BigDecimal d=bd(r[0]),p=bd(r[1]);return new FinanceSummary(sid,d,p,d.subtract(p).max(BigDecimal.ZERO),((Number)r[2]).longValue());}
 public List<Charge> charges(Long sid){Child c=owned(sid);if(c.enrollmentId()==null)return List.of();List<Object[]> rows=em.createNativeQuery("select sc.id,sc.label,sc.original_amount,sc.discount_amount,sc.final_amount,coalesce(sum(case when p.status not in ('CANCELLED','ANNULE') then pa.amount else 0 end),0),sc.due_date,sc.status from student_charge sc left join payment_allocation pa on pa.student_charge_id=sc.id left join payment p on p.id=pa.payment_id where sc.student_enrollment_id=:e and sc.status not in ('CANCELLED','ANNULE') group by sc.id order by sc.due_date nulls last,sc.id").setParameter("e",c.enrollmentId()).getResultList();List<Charge> o=new ArrayList<>();for(Object[]r:rows){BigDecimal fin=bd(r[4]),pay=bd(r[5]);o.add(new Charge(l(r[0]),str(r[1]),bd(r[2]),bd(r[3]),fin,pay,fin.subtract(pay).max(BigDecimal.ZERO),date(r[6]),str(r[7])));}return o;}
 public List<PaymentItem> payments(){Long g=guardianId();List<Object[]> rows=em.createNativeQuery("select p.id,p.payment_number,p.payment_date,p.total_amount,p.status,pm.name,p.external_reference from payment p join payment_method pm on pm.id=p.payment_method_id where p.guardian_id=:g order by p.payment_date desc,p.id desc").setParameter("g",g).getResultList();List<PaymentItem> o=new ArrayList<>();for(Object[]r:rows)o.add(new PaymentItem(l(r[0]),str(r[1]),odt(r[2]),bd(r[3]),str(r[4]),str(r[5]),str(r[6])));return o;}
 public List<AttendanceItem> attendance(Long sid){owned(sid);List<Object[]> rows=em.createNativeQuery("select a.id,cs.session_date,s.name,a.attendance_status,a.late_minutes,a.reason,a.justified from student_attendance a join class_session cs on cs.id=a.class_session_id join subject s on s.id=cs.subject_id where a.student_id=:s order by cs.session_date desc,a.id desc").setParameter("s",sid).getResultList();List<AttendanceItem>o=new ArrayList<>();for(Object[]r:rows)o.add(new AttendanceItem(l(r[0]),date(r[1]),str(r[2]),str(r[3]),r[4]==null?null:((Number)r[4]).intValue(),str(r[5]),Boolean.TRUE.equals(r[6])));return o;}
 public List<TimetableItem> timetable(Long sid){Child c=owned(sid);if(c.classGroupId()==null)return List.of();List<Object[]> rows=em.createNativeQuery("select se.id,se.day_of_week,ts.start_time,ts.end_time,s.name,concat(p.first_name,' ',p.last_name),cg.name from schedule_entry se join teaching_assignment ta on ta.id=se.teaching_assignment_id join time_slot ts on ts.id=se.time_slot_id join subject s on s.id=ta.subject_id join teacher t on t.id=ta.teacher_id join employee e on e.id=t.employee_id join person p on p.id=e.person_id join class_group cg on cg.id=ta.class_group_id where ta.class_group_id=:c and se.status='ACTIVE' and ta.status='ACTIVE' order by se.day_of_week,ts.display_order").setParameter("c",c.classGroupId()).getResultList();List<TimetableItem>o=new ArrayList<>();for(Object[]r:rows)o.add(new TimetableItem(l(r[0]),str(r[1]),str(r[2]),str(r[3]),str(r[4]),str(r[5]),str(r[6])));return o;}
 public List<ExerciseItem> exercises(Long sid){Child c=owned(sid);if(c.classGroupId()==null)return List.of();List<Object[]> rows=em.createNativeQuery("select x.id,x.title,x.description,x.instructions,x.due_date,x.status,s.name,cg.name from teacher_exercise x join teaching_assignment ta on ta.id=x.teaching_assignment_id join subject s on s.id=ta.subject_id join class_group cg on cg.id=ta.class_group_id where ta.class_group_id=:c and x.status<>'DRAFT' order by x.due_date desc nulls last,x.id desc").setParameter("c",c.classGroupId()).getResultList();List<ExerciseItem>o=new ArrayList<>();for(Object[]r:rows)o.add(new ExerciseItem(l(r[0]),str(r[1]),str(r[2]),str(r[3]),date(r[4]),str(r[5]),str(r[6]),str(r[7])));return o;}
 public List<GradeItem> grades(Long sid){owned(sid);List<Object[]> rows=em.createNativeQuery("select ev.id,ev.title,s.name,ev.evaluation_date,ev.max_score,g.score,g.absent,g.comment from teacher_evaluation_grade g join teacher_evaluation ev on ev.id=g.evaluation_id join teaching_assignment ta on ta.id=ev.teaching_assignment_id join subject s on s.id=ta.subject_id where g.student_id=:s and ev.status<>'DRAFT' order by ev.evaluation_date desc,ev.id desc").setParameter("s",sid).getResultList();List<GradeItem>o=new ArrayList<>();for(Object[]r:rows)o.add(new GradeItem(l(r[0]),str(r[1]),str(r[2]),date(r[3]),bd(r[4]),r[5]==null?null:bd(r[5]),Boolean.TRUE.equals(r[6]),str(r[7])));return o;}
 private static Long l(Object o){return o==null?null:((Number)o).longValue();}private static String str(Object o){return o==null?null:o.toString();}private static BigDecimal bd(Object o){return o==null?BigDecimal.ZERO:(o instanceof BigDecimal b?b:new BigDecimal(o.toString()));}private static LocalDate date(Object o){if(o==null)return null;if(o instanceof LocalDate d)return d;if(o instanceof java.sql.Date d)return d.toLocalDate();return LocalDate.parse(o.toString());}private static OffsetDateTime odt(Object o){if(o instanceof OffsetDateTime x)return x;if(o instanceof Timestamp t)return t.toInstant().atOffset(ZoneOffset.UTC);return OffsetDateTime.parse(o.toString());}
}
